css:
*, *::before, *::after { font-family: ui-monospace, "JetBrains Mono", "Fira Code", "SF Mono", Menlo, "DejaVu Sans Mono", "Liberation Mono", monospace !important; }
/* background: dithered planet, dimmed 70% behind the message column, easing out to 30% over 16rem on each side (eased stops avoid a visible edge) */
.dark [data-workspace-area="conversation"] {
  --mono-l: calc(50% - var(--chat-content-max-width, 46rem) / 2);
  --mono-r: calc(50% + var(--chat-content-max-width, 46rem) / 2);
  background: linear-gradient(90deg,
    rgba(0,0,0,0.30) calc(var(--mono-l) - 16rem),
    rgba(0,0,0,0.318) calc(var(--mono-l) - 14rem),
    rgba(0,0,0,0.366) calc(var(--mono-l) - 12rem),
    rgba(0,0,0,0.433) calc(var(--mono-l) - 10rem),
    rgba(0,0,0,0.51) calc(var(--mono-l) - 8rem),
    rgba(0,0,0,0.587) calc(var(--mono-l) - 6rem),
    rgba(0,0,0,0.654) calc(var(--mono-l) - 4rem),
    rgba(0,0,0,0.702) calc(var(--mono-l) - 2rem),
    rgba(0,0,0,0.72) var(--mono-l),
    rgba(0,0,0,0.72) var(--mono-r),
    rgba(0,0,0,0.702) calc(var(--mono-r) + 2rem),
    rgba(0,0,0,0.654) calc(var(--mono-r) + 4rem),
    rgba(0,0,0,0.587) calc(var(--mono-r) + 6rem),
    rgba(0,0,0,0.51) calc(var(--mono-r) + 8rem),
    rgba(0,0,0,0.433) calc(var(--mono-r) + 10rem),
    rgba(0,0,0,0.366) calc(var(--mono-r) + 12rem),
    rgba(0,0,0,0.318) calc(var(--mono-r) + 14rem),
    rgba(0,0,0,0.30) calc(var(--mono-r) + 16rem)),
  var(--theme-background-image) right top / cover no-repeat, #000 !important;
  image-rendering: pixelated;
}
/* new/empty threads: the timeline draws an opaque placeholder over the chat area; let the background show through */
.dark [data-workspace-area="conversation"] [data-timeline-loading] { background: transparent !important; }
